// src/shared/net.ts
var MAP_ENVIRONMENT_TO_BASE_URL = {
  dev: "https://fib-dev.fib.iq",
  stage: "https://fib-stage.fib.iq",
  prod: "https://fib.prod.fib.iq"
};
var BaseHTTP = class {
  #baseUrl;
  #clientId;
  #clientSecret;
  #grantType = "client_credentials";
  constructor(clientId, clientSecret, env) {
    const rawBaseURL = MAP_ENVIRONMENT_TO_BASE_URL[env];
    if (!rawBaseURL) {
      throw new Error(`Invalid environment: ${env}`);
    }
    this.#clientId = clientId;
    this.#clientSecret = clientSecret;
    this.#baseUrl = new URL(rawBaseURL);
  }
  getBaseUrl() {
    return this.#baseUrl;
  }
  getHeaders(accessToken, omitContentType = false) {
    const headers = new Headers();
    if (!omitContentType) headers.set("Content-Type", "application/json");
    headers.set("X-Application-Type", "3rd-party");
    headers.set("X-Application-Platform", "node");
    headers.set("Authorization", `Bearer ${accessToken}`);
    return headers;
  }
  async authenticate(signal) {
    const url = new URL(
      "/auth/realms/fib-online-shop/protocol/openid-connect/token",
      this.#baseUrl
    );
    const body = new URLSearchParams();
    body.set("grant_type", this.#grantType);
    body.set("client_id", this.#clientId);
    body.set("client_secret", this.#clientSecret);
    return fetch(url.href, {
      body,
      signal,
      method: "POST"
    });
  }
};

// src/shared/utils.ts
function formatISODuration(duration) {
  const parts = ["P"];
  if (duration.years) parts.push(`${duration.years}Y`);
  if (duration.months) parts.push(`${duration.months}M`);
  if (duration.weeks) parts.push(`${duration.weeks}W`);
  if (duration.days) parts.push(`${duration.days}D`);
  const hasTimeComponents = duration.hours || duration.minutes || duration.seconds;
  if (hasTimeComponents) {
    parts.push("T");
    if (duration.hours) parts.push(`${duration.hours}H`);
    if (duration.minutes) parts.push(`${duration.minutes}M`);
    if (duration.seconds) parts.push(`${duration.seconds}S`);
  }
  return parts.length === 1 ? "P0D" : parts.join("");
}
console.log(formatISODuration({ days: 1 }));

// src/payment/net.ts
var HTTP = class extends BaseHTTP {
  constructor(clientId, clientSecret, env) {
    super(clientId, clientSecret, env);
  }
  static getClient(clientId, clientSecret, env) {
    return new this(clientId, clientSecret, env);
  }
  async createPayment({
    amount,
    description,
    expiresIn,
    refundableFor,
    redirectUri,
    statusCallbackUrl
  }, accessToken, signal) {
    const url = new URL("/protected/v1/payments", this.getBaseUrl());
    const body = {
      description,
      redirectUri: redirectUri?.toString(),
      statusCallbackUrl: statusCallbackUrl?.toString(),
      refundableFor: refundableFor ? formatISODuration(refundableFor) : void 0,
      expiresIn: expiresIn ? formatISODuration(expiresIn) : void 0,
      monetaryValue: { amount, currency: "IQD" }
    };
    return fetch(url.href, {
      signal,
      method: "POST",
      body: JSON.stringify(body),
      headers: this.getHeaders(accessToken)
    });
  }
  async getPaymentStatus(paymentId, accessToken, signal) {
    const url = new URL(
      `/protected/v1/payments/${paymentId}/status`,
      this.getBaseUrl()
    );
    return fetch(url.href, {
      signal,
      method: "GET",
      headers: this.getHeaders(accessToken)
    });
  }
  async cancelPayment(paymentId, accessToken, signal) {
    const url = new URL(
      `/protected/v1/payments/${paymentId}/cancel`,
      this.getBaseUrl()
    );
    return fetch(url.href, {
      signal,
      method: "POST",
      headers: this.getHeaders(accessToken)
    });
  }
  async refundPayment(paymentId, accessToken, signal) {
    const url = new URL(
      `/protected/v1/payments/${paymentId}/refund`,
      this.getBaseUrl()
    );
    return fetch(url.href, {
      signal,
      method: "POST",
      headers: this.getHeaders(accessToken)
    });
  }
};

// src/payment/index.ts
var PaymentSDK = class {
  #http;
  #environment;
  constructor(clientId, clientSecret, environment) {
    this.#environment = environment;
    this.#http = HTTP.getClient(clientId, clientSecret, this.#environment);
  }
  authenticate(signal) {
    return this.#http.authenticate(signal);
  }
  createPayment({
    amount,
    description,
    expiresIn,
    refundableFor,
    redirectUri,
    statusCallbackUrl
  }, accessToken, signal) {
    return this.#http.createPayment(
      {
        amount,
        description,
        expiresIn,
        refundableFor,
        redirectUri,
        statusCallbackUrl
      },
      accessToken,
      signal
    );
  }
  getPaymentStatus(paymentId, accessToken, signal) {
    return this.#http.getPaymentStatus(paymentId, accessToken, signal);
  }
  cancelPayment(paymentId, accessToken, signal) {
    return this.#http.cancelPayment(paymentId, accessToken, signal);
  }
  refundPayment(paymentId, accessToken, signal) {
    return this.#http.refundPayment(paymentId, accessToken, signal);
  }
  static getClient = (clientId, clientSecret, environment) => {
    return new this(clientId, clientSecret, environment);
  };
};
export {
  PaymentSDK
};
